-- Washington ZIP code centroids (ZCTA internal points), US Census 2024 Gazetteer — public domain.
-- Source: https://www2.census.gov/geo/docs/maps-data/data/gazetteer/2024_Gazetteer/2024_Gaz_zcta_national.zip
-- Used to place teens and jobs without storing street addresses in searchable form.

create table public.zip_centroids (
  zip      text primary key check (zip ~ '^\d{5}$'),
  state    text not null default 'WA',
  location extensions.geography(point, 4326) not null
);

alter table public.zip_centroids enable row level security;
create policy "zip_centroids: readable by signed-in users" on public.zip_centroids for select to authenticated using (true);
grant select on public.zip_centroids to authenticated;

